CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, first_name TEXT NOT NULL, course TEXT NOT NULL, review TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS review_rate_limits (ip_hash TEXT PRIMARY KEY, window_start INTEGER NOT NULL, submissions INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_reviews_created_at ON reviews(created_at DESC);
